import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double x = sc.nextDouble();
        double y = sc.nextDouble();
        int n = sc.nextInt();

        double minDiff = Double.MAX_VALUE;
        double bestX = 0;
        double bestY = 1;

        for (int i = 1; i <= n; i++) {
            double val = (x * i) / y;
            double floorVal = Math.floor(val);
            if (Math.abs((x / y) - (floorVal / i)) < minDiff) {
                minDiff = Math.abs((x / y) - (floorVal / i));
                bestX = floorVal;
                bestY = i;
            }
            double ceilVal = Math.ceil(val);
            if (Math.abs((x / y) - (ceilVal / i)) < minDiff) {
                minDiff = Math.abs((x / y) - (ceilVal / i));
                bestX = ceilVal;
                bestY = i;
            }
        }
        System.out.println((long) bestX + "/" + (long) bestY);
    }
}
